#include <stdlib.h>
#include <string.h>

#if defined(__AVX512F__)
#include <immintrin.h>
#define MR 12
#define NR 32
#define MS 8   /* MR-strips per task  (96 rows)  */
#define NS 8   /* NR-strips per task  (256 cols) */
#elif defined(__AVX2__) && defined(__FMA__)
#include <immintrin.h>
#define MR 6
#define NR 16
#define MS 12  /* 72 rows  */
#define NS 16  /* 256 cols */
#else
#define MR 4
#define NR 16
#define MS 16
#define NS 16
#endif

#define KC 256

static float *Abuf = NULL, *Bbuf = NULL;
static size_t Acap = 0, Bcap = 0;

static float *grow(float *p, size_t *cap, size_t need)
{
    if (need <= *cap) return p;
    free(p);
    size_t bytes = (need * sizeof(float) + 63) & ~(size_t)63;
    p = (float *)aligned_alloc(64, bytes);
    *cap = need;
    return p;
}

#if defined(__AVX512F__)
static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict c, int ldc, int first)
{
    __m512 acc0[MR], acc1[MR];
#pragma GCC unroll 12
    for (int r = 0; r < MR; r++) {
        acc0[r] = _mm512_setzero_ps();
        acc1[r] = _mm512_setzero_ps();
    }
    for (int k = 0; k < kc; k++) {
        __m512 b0 = _mm512_loadu_ps(b);
        __m512 b1 = _mm512_loadu_ps(b + 16);
#pragma GCC unroll 12
        for (int r = 0; r < MR; r++) {
            __m512 av = _mm512_set1_ps(a[r]);
            acc0[r] = _mm512_fmadd_ps(av, b0, acc0[r]);
            acc1[r] = _mm512_fmadd_ps(av, b1, acc1[r]);
        }
        a += MR;
        b += NR;
    }
#pragma GCC unroll 12
    for (int r = 0; r < MR; r++) {
        float *cr = c + (size_t)r * ldc;
        if (first) {
            _mm512_storeu_ps(cr, acc0[r]);
            _mm512_storeu_ps(cr + 16, acc1[r]);
        } else {
            _mm512_storeu_ps(cr, _mm512_add_ps(_mm512_loadu_ps(cr), acc0[r]));
            _mm512_storeu_ps(cr + 16, _mm512_add_ps(_mm512_loadu_ps(cr + 16), acc1[r]));
        }
    }
}
#elif defined(__AVX2__) && defined(__FMA__)
static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict c, int ldc, int first)
{
    __m256 acc0[MR], acc1[MR];
#pragma GCC unroll 6
    for (int r = 0; r < MR; r++) {
        acc0[r] = _mm256_setzero_ps();
        acc1[r] = _mm256_setzero_ps();
    }
    for (int k = 0; k < kc; k++) {
        __m256 b0 = _mm256_loadu_ps(b);
        __m256 b1 = _mm256_loadu_ps(b + 8);
#pragma GCC unroll 6
        for (int r = 0; r < MR; r++) {
            __m256 av = _mm256_broadcast_ss(a + r);
            acc0[r] = _mm256_fmadd_ps(av, b0, acc0[r]);
            acc1[r] = _mm256_fmadd_ps(av, b1, acc1[r]);
        }
        a += MR;
        b += NR;
    }
#pragma GCC unroll 6
    for (int r = 0; r < MR; r++) {
        float *cr = c + (size_t)r * ldc;
        if (first) {
            _mm256_storeu_ps(cr, acc0[r]);
            _mm256_storeu_ps(cr + 8, acc1[r]);
        } else {
            _mm256_storeu_ps(cr, _mm256_add_ps(_mm256_loadu_ps(cr), acc0[r]));
            _mm256_storeu_ps(cr + 8, _mm256_add_ps(_mm256_loadu_ps(cr + 8), acc1[r]));
        }
    }
}
#else
static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict c, int ldc, int first)
{
    float acc[MR][NR];
    memset(acc, 0, sizeof(acc));
    for (int k = 0; k < kc; k++) {
        for (int r = 0; r < MR; r++) {
            float av = a[r];
            for (int j = 0; j < NR; j++)
                acc[r][j] += av * b[j];
        }
        a += MR;
        b += NR;
    }
    for (int r = 0; r < MR; r++) {
        float *cr = c + (size_t)r * ldc;
        if (first)
            for (int j = 0; j < NR; j++) cr[j] = acc[r][j];
        else
            for (int j = 0; j < NR; j++) cr[j] += acc[r][j];
    }
}
#endif

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    const int ms = (n + MR - 1) / MR, ns = (n + NR - 1) / NR;
    const int Mpad = ms * MR, Npad = ns * NR;
    const int nks = (n + KC - 1) / KC;
    const int mb = (ms + MS - 1) / MS, nb = (ns + NS - 1) / NS;

    Abuf = grow(Abuf, &Acap, (size_t)Mpad * n);
    Bbuf = grow(Bbuf, &Bcap, (size_t)Npad * n);
    float *restrict Ap = Abuf;
    float *restrict Bp = Bbuf;

#pragma omp parallel
    {
        /* Pack A: [kb][strip][k][MR] */
#pragma omp for collapse(2) schedule(static)
        for (int kb = 0; kb < nks; kb++)
            for (int s = 0; s < ms; s++) {
                int k0 = kb * KC, kc = n - k0 < KC ? n - k0 : KC;
                int i0 = s * MR;
                float *dst = Ap + (size_t)k0 * Mpad + (size_t)s * MR * kc;
                for (int r = 0; r < MR; r++) {
                    int i = i0 + r;
                    if (i < n) {
                        const float *src = A + (size_t)i * n + k0;
                        for (int k = 0; k < kc; k++) dst[k * MR + r] = src[k];
                    } else {
                        for (int k = 0; k < kc; k++) dst[k * MR + r] = 0.0f;
                    }
                }
            }

        /* Pack B: [kb][strip][k][NR] */
#pragma omp for collapse(2) schedule(static)
        for (int kb = 0; kb < nks; kb++)
            for (int t = 0; t < ns; t++) {
                int k0 = kb * KC, kc = n - k0 < KC ? n - k0 : KC;
                int j0 = t * NR, nr = n - j0 < NR ? n - j0 : NR;
                float *dst = Bp + (size_t)k0 * Npad + (size_t)t * NR * kc;
                for (int k = 0; k < kc; k++) {
                    const float *src = B + (size_t)(k0 + k) * n + j0;
                    float *d = dst + (size_t)k * NR;
                    int j = 0;
                    for (; j < nr; j++) d[j] = src[j];
                    for (; j < NR; j++) d[j] = 0.0f;
                }
            }

#pragma omp for collapse(2) schedule(dynamic)
        for (int p = 0; p < mb; p++)
            for (int q = 0; q < nb; q++) {
                int s0 = p * MS, s1 = s0 + MS < ms ? s0 + MS : ms;
                int t0 = q * NS, t1 = t0 + NS < ns ? t0 + NS : ns;
                float tmp[MR * NR] __attribute__((aligned(64)));
                for (int kb = 0; kb < nks; kb++) {
                    int k0 = kb * KC, kc = n - k0 < KC ? n - k0 : KC;
                    const float *Ablk = Ap + (size_t)k0 * Mpad;
                    const float *Bblk = Bp + (size_t)k0 * Npad;
                    for (int t = t0; t < t1; t++) {
                        const float *bs = Bblk + (size_t)t * NR * kc;
                        int j0 = t * NR, nr = n - j0 < NR ? n - j0 : NR;
                        for (int s = s0; s < s1; s++) {
                            const float *as = Ablk + (size_t)s * MR * kc;
                            int i0 = s * MR, mr = n - i0 < MR ? n - i0 : MR;
                            float *cp = C + (size_t)i0 * n + j0;
                            if (mr == MR && nr == NR) {
                                kernel(kc, as, bs, cp, n, kb == 0);
                            } else {
                                kernel(kc, as, bs, tmp, NR, 1);
                                for (int r = 0; r < mr; r++) {
                                    float *cr = cp + (size_t)r * n;
                                    const float *tr = tmp + r * NR;
                                    if (kb == 0)
                                        for (int j = 0; j < nr; j++) cr[j] = tr[j];
                                    else
                                        for (int j = 0; j < nr; j++) cr[j] += tr[j];
                                }
                            }
                        }
                    }
                }
            }
    }
}
